import csv
import io
import re
import collections
import typing

_DELIMITER = ";"
_QUOTECHAR = '"'
_EXPECTED_WIDTH = 9


def _parse_with_csv(text: str) -> typing.List[typing.List[str]]:
    try:
        csv.field_size_limit(2 ** 31 - 1)
    except (OverflowError, ValueError):
        pass

    stream = io.StringIO(text, newline="")
    reader = csv.reader(
        stream,
        delimiter=_DELIMITER,
        quotechar=_QUOTECHAR,
        doublequote=True,
        skipinitialspace=False,
        strict=False,
    )
    return [list(row) for row in reader]


def _parse_tolerantly(text: str) -> typing.List[typing.List[str]]:
    records: typing.List[typing.List[str]] = []
    row: typing.List[str] = []
    field: typing.List[str] = []
    in_quotes = False
    at_field_start = True
    record_started = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if in_quotes:
            if ch == _QUOTECHAR:
                if i + 1 < n and text[i + 1] == _QUOTECHAR:
                    field.append(_QUOTECHAR)
                    i += 2
                    record_started = True
                    continue
                in_quotes = False
                i += 1
                continue

            field.append(ch)
            record_started = True
            i += 1
            continue

        if ch == _QUOTECHAR and at_field_start:
            in_quotes = True
            at_field_start = False
            record_started = True
            i += 1
            continue

        if ch == _DELIMITER:
            row.append("".join(field))
            field = []
            at_field_start = True
            record_started = True
            i += 1
            continue

        if ch == "\r" or ch == "\n":
            row.append("".join(field))
            records.append(row)
            row = []
            field = []
            at_field_start = True
            record_started = False
            if ch == "\r" and i + 1 < n and text[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(ch)
        at_field_start = False
        record_started = True
        i += 1

    if record_started or row or field:
        row.append("".join(field))
        records.append(row)

    return records


def _parse_records(text: str) -> typing.List[typing.List[str]]:
    try:
        return _parse_with_csv(text)
    except (csv.Error, UnicodeError, ValueError):
        return _parse_tolerantly(text)


def _value_kind(value: str) -> str:
    value = value.strip()
    if not value:
        return "blank"
    if re.fullmatch(r"[+-]?(?:[$€£¥]\s*)?\d+(?:[.,]\d+)?%?", value):
        return "number"
    if re.fullmatch(r"\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}", value):
        return "date"
    if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?(?:\s*[AaPp][Mm])?", value):
        return "time"
    if re.match(r"(?i)^(?:https?|ftp)://", value):
        return "url"
    return "text"


def _header_score(
    records: typing.List[typing.List[str]], index: int, width: int
) -> int:
    candidate = records[index]
    score = 0

    for value in candidate:
        stripped = value.strip()
        kind = _value_kind(value)

        if kind == "text":
            score += 2
        elif kind != "blank":
            score -= 3

        if stripped and len(stripped) <= 80 and re.search(r"[A-Za-z]", stripped):
            score += 1

    following = [
        row for row in records[index + 1:index + 7] if len(row) == width
    ]

    if following:
        for column in range(width):
            header_kind = _value_kind(candidate[column])
            counts = collections.Counter(_value_kind(row[column]) for row in following)
            common_kind = counts.most_common(1)[0][0]
            if header_kind == "text" and common_kind != "text":
                score += 4
            elif header_kind != common_kind:
                score += 1

    if index == 0 or len(records[index - 1]) != width:
        score += 3

    run = 0
    for row in records[index + 1:index + 12]:
        if len(row) == width:
            run += 1
        else:
            break
    score += min(run, 5)

    return score


def _find_header_index(
    records: typing.List[typing.List[str]], width: int
) -> typing.Optional[int]:
    candidates = [
        i
        for i, row in enumerate(records)
        if len(row) == width and any(value != "" for value in row)
    ]
    if not candidates:
        return None

    best_index = candidates[0]
    best_score = _header_score(records, best_index, width)

    for index in candidates[1:]:
        score = _header_score(records, index, width)
        if score > best_score:
            best_index = index
            best_score = score

    return best_index


def _recover_at_physical_line(
    text: str, width: int
) -> typing.Optional[typing.List[typing.List[str]]]:
    lines = text.splitlines(keepends=True)
    offset = 0

    for line in lines:
        if line.count(_DELIMITER) >= width - 1:
            suffix = text[offset:]
            parsed = _parse_records(suffix)
            if parsed and len(parsed[0]) == width:
                return parsed
        offset += len(line)

    return None


def _make_extra_columns(
    columns: typing.List[str], target_width: int
) -> typing.List[str]:
    result = list(columns)
    used = set(result)
    number = 1

    while len(result) < target_width:
        name = "extra_" + str(number)
        number += 1
        while name in used:
            name = "extra_" + str(number)
            number += 1
        result.append(name)
        used.add(name)

    return result


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raise TypeError("raw_csv must be a string")

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = _parse_records(raw_csv)
    if not records:
        return {"columns": [], "rows": []}

    header_index = _find_header_index(records, _EXPECTED_WIDTH)

    if header_index is None:
        recovered = _recover_at_physical_line(raw_csv, _EXPECTED_WIDTH)
        if recovered is not None:
            records = recovered
            header_index = 0

    if header_index is None:
        nonempty = [
            (i, row)
            for i, row in enumerate(records)
            if row and any(value != "" for value in row)
        ]
        if not nonempty:
            return {"columns": [], "rows": []}

        width_counts = collections.Counter(len(row) for _, row in nonempty)
        selected_width = width_counts.most_common(1)[0][0]
        matching = [i for i, row in nonempty if len(row) == selected_width]
        header_index = matching[0] if matching else nonempty[0][0]

    columns = list(records[header_index])
    rows = [list(row) for row in records[header_index + 1:]]

    target_width = max(
        [len(columns)] + [len(row) for row in rows],
        default=len(columns),
    )
    columns = _make_extra_columns(columns, target_width)

    normalized_rows: typing.List[typing.List[str]] = []
    for row in rows:
        if len(row) < target_width:
            row = row + [""] * (target_width - len(row))
        normalized_rows.append(row)

    return {"columns": columns, "rows": normalized_rows}
